async function panel(){if(!meta)return;const ver=++panelVersion,studyVer=loadVersion;const queries=$('panelInput').value.split(/[,\s]+/).filter(Boolean);if(queries.length>6){status('Please enter up to six gene symbols.',true);return}const ids=[...new Set(queries.map(q=>genes.findIndex(g=>g.toUpperCase()===q.toUpperCase())))];if(ids.includes(-1)||!ids.length){status('One or more panel genes are not retained in this study. Check their symbols.',true);return}try{const vs=await Promise.all(ids.map(i=>expression(i)));if(ver!==panelVersion||studyVer!==loadVersion)return;let s='<svg viewBox="0 0 1000 '+(120+meta.groups.length*33)+'" role="img" aria-label="Gene panel dot plot">';const pts=meta.groups.map(g=>vs.map(v=>stats(cells.cluster.map((c,i)=>c===g.id?i:-1).filter(i=>i>=0),v)));const max=Math.max(.01,...pts.flat().map(p=>p.mean));ids.forEach((id,j)=>{s+=`<text x="${270+j*100}" y="30" text-anchor="middle" fill="#18332f" font-size="15">${escape(genes[id])}</text>`});meta.groups.forEach((g,i)=>{s+=`<text x="5" y="${67+i*33}" font-size="13" fill="#52675c">${escape(g.name)}</text>`;pts[i].forEach((p,j)=>{s+=`<circle cx="${270+j*100}" cy="${62+i*33}" r="${p.pct?2+Math.sqrt(p.pct/100)*10:0}" fill="${geneColor(p.mean,max)}"><title>${escape(g.name)}: mean ${p.mean.toFixed(3)}, ${p.pct.toFixed(1)}% detected</title></circle>`})});s+=`<text x="5" y="${100+meta.groups.length*33}" font-size="13" fill="#60756d">All retained cells · dot area increases with detection · color range 0 to ${max.toFixed(2)} ln(1 + CP10K)</text></svg>`;$('dotplot').innerHTML=s;renderHeatmap(ids,vs);status('')}catch(e){status(e.message,true)}}
$('panelForm').onsubmit=e=>{e.preventDefault();void panel()};
function renderRanking(){if(!summary)return;const mode=$('rankMode').value,q=$('rankSearch').value.trim().toUpperCase();rankRows=genes.map((g,i)=>({g,i,s:summary[i],delta:meta.id==='GSE178121'?summary[i][3]-summary[i][2]:Math.max(...summary[i].slice(2))-Math.min(...summary[i].slice(2))})).filter(r=>r.g.toUpperCase().includes(q));rankRows.sort((a,b)=>mode==='mean'?b.s[0]-a.s[0]:mode==='detection'?b.s[1]-a.s[1]:Math.abs(b.delta)-Math.abs(a.delta));$('deltaHeader').textContent=meta.id==='GSE178121'?'Δ diabetes − control':'Range across samples';$('ranking').innerHTML=rankRows.slice(0,50).map(r=>`<tr><td><b>${escape(r.g)}</b></td><td>${r.s[0].toFixed(3)}</td><td>${r.s[1].toFixed(1)}%</td><td>${r.delta.toFixed(3)}</td><td><button data-gene="${escape(r.g)}">Explore</button></td></tr>`).join('')||'<tr><td colspan="5">No matching genes.</td></tr>';$('ranking').querySelectorAll('button').forEach(b=>b.onclick=()=>{setView('explore');void selectGene(b.dataset.gene)})}
$('rankMode').onchange=renderRanking;$('rankSearch').oninput=renderRanking;$('exportRanking').onclick=()=>{if(!meta)return;download(`${meta.id}-descriptive-ranking.csv`,csv([['dataset','gene','mean_ln1p_CP10K','pct_detected',meta.id==='GSE178121'?'diabetes_minus_control_mean_log':'sample_mean_log_range',...meta.samples.map(s=>s+'_mean_log')],...rankRows.map(r=>[meta.id,r.g,...r.s.slice(0,2),r.delta,...r.s.slice(2)])]))};
function methods(){$('methodDetails').innerHTML=`<p><b>${escape(meta.id)}</b>: ${fmt(meta.inputCells)} cells in imported matrices; ${fmt(meta.removedCells)} excluded; ${fmt(meta.cells)} retained.</p>${meta.partialImport?`<p class="note"><b>Partial import.</b> ${(meta.excludedMatrices||[]).map(x=>escape(x.sample+': '+x.reason)).join('; ')}</p>`:''}<p>${escape(meta.title)}</p><p>${escape(meta.design)}</p><details><summary>Deposited sample descriptions</summary>${Object.entries(meta.sampleMetadata||{}).map(([id,m])=>`<p><b>${escape(id)}</b> ${escape([...(m.title||[]),...(m.source_name_ch1||[]),...(m.characteristics_ch1||[])].join(' · '))}</p>`).join('')}</details><p>${escape(meta.normalization)}</p><p>${escape(meta.qc)}</p><p>${escape(meta.embedding)} ${escape(meta.tsneMethod||'')}</p><p>${escape(meta.clustering)}</p><p>All retained genes are searchable. The backend retrieves and processes public data as import jobs, then serves gene vectors on demand. Automatic source checks run on visits. Owner access is required for analyses, manual imports and retries.</p><details><summary>Downloaded files and checksums</summary>${(meta.provenance||[]).map(p=>`<p><a href="${escape(p.url)}" target="_blank" rel="noopener">${escape(p.file)}</a><br>${fmt(p.bytes)} bytes<br><small>SHA-256: ${escape(p.sha256)}</small></p>`).join('')}</details><p>Marker evidence is available per group:</p><ul>${meta.groups.map(g=>`<li><b>${escape(g.name)}</b>: top enriched mean-expression markers ${g.markers.map(escape).join(', ')}</li>`).join('')}</ul>`}
async function refreshStudies(snapshot=null){if(sessionPaused)return;try{const result=snapshot||await get(API+'/studies');librarySnapshot=result;studyRows=result.studies;if(statusSource==='catalog'||!meta)status('');renderFreshness(result.freshness||{});const ready=studyRows.filter(r=>r.status==='ready');manifest={datasets:ready};$('dataset').innerHTML=ready.map(r=>`<option value="${escape(r.id)}">${escape(r.id+' · '+humanText(r.title))}</option>`).join('');if(meta)$('dataset').value=meta.id;$('importSummary').textContent=`${ready.length} ready · ${studyRows.filter(r=>['queued','running','publishing'].includes(r.status)).length} processing · ${studyRows.length} discovered`;$('importProgress').innerHTML=studyRows.map(r=>`<article class="studyrow"><div><span class="tag">${escape(r.status||'discovering')}</span><h3>${escape(r.id)} · ${escape(r.title||'')}</h3><p>${escape(r.message||'')}</p>${r.refreshMessage?`<p>Update: ${escape(r.refreshMessage)}</p>`:''}${r.cells?`<small>${fmt(r.cells)} cells · ${fmt(r.genes)} genes</small>`:''}</div>${['failed','unavailable','access_review','raw_reads','controlled_access'].includes(r.status)?`<button data-retry="${escape(r.id)}">Retry source</button>`:''}<a target="_blank" rel="noopener" href="${escape(r.source||'#')}">Repository</a></article>`).join('');$('importProgress').querySelectorAll('[data-retry]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await post('/retry/'+b.dataset.retry);await refreshStudies()}catch(e){status(e.message,true)}finally{b.disabled=false}});renderStudyTable();$('release').textContent='v3.1 · Public repository data · Provisional cell labels';if(!meta&&ready.length&&currentId){const target=ready.find(r=>r.id===currentId);if(target)await loadStudy(target.id,true)}if(!ready.length)status('Automatic imports are running. See source status below.');}catch(e){status('Processing service: '+e.message,true,'catalog');if(!librarySnapshot){$('loadedStudies').innerHTML='<tr><td colspan="8">The data service is currently unavailable. Retrying automatically.</td></tr>';}}}
function studyTissue(r){const text=(r.title||'').toLowerCase();if(r.id==='GSE175499')return 'reference';if(/fibrovascular|fibrous membrane|epiretinal|proliferative vitreoretinopathy/.test(text))return 'membrane';if(/circulating|pbmc|peripheral blood|peripheral immune/.test(text))return 'blood';if(/retin|macular|microglia|vldlr|ocular/.test(text))return 'retina';return 'reference'}
function renderStudyTable(){if(!librarySnapshot)return;const search=$('studySearch').value.toLowerCase(),sort=$('studySort').value;const rows=studyRows.filter(r=>r.status==='ready'&&(activeTissue==='all'||studyTissue(r)===activeTissue)&&humanText(`${r.id} ${r.title} ${r.species}`).toLowerCase().includes(search)).sort((a,b)=>sort==='cells'?b.cells-a.cells:String(sort==='accession'?a.id:a[sort]||'').localeCompare(String(sort==='accession'?b.id:b[sort]||''),undefined,{numeric:true}));const size=+$('rowsPerPage').value;studyPage=Math.min(studyPage,Math.max(0,Math.ceil(rows.length/size)-1));const from=studyPage*size;const tissues={retina:'retina',membrane:'fibrovascular membrane',blood:'blood / immune',reference:'reference'};const species=s=>String(s||'See source').replace('Homo sapiens','human').replace('Mus musculus','mouse').replace('Rattus norvegicus','rat');$('loadedStudies').innerHTML=rows.slice(from,from+size).map(r=>`<tr class="${meta?.id===r.id?'selected':''}"><td><input type="radio" name="studyRow" aria-label="Select ${escape(r.id)}" value="${escape(r.id)}" ${meta?.id===r.id?'checked':''}></td><td><button class="expand-row" data-expand="${escape(r.id)}" aria-label="${expandedStudies.has(r.id)?'Collapse':'Expand'} ${escape(r.id)} details" aria-expanded="${expandedStudies.has(r.id)}">${expandedStudies.has(r.id)?'▾':'▸'}</button></td><td title="${escape(humanText(r.title))}">${escape(humanText(r.title))}</td><td>${escape(species(r.species))}</td><td>${r.id==='GSE204880'?'kidney / retina':tissues[studyTissue(r)]}</td><td>${/single.nucle|snRNA/i.test(r.title)?'snRNA-seq':'scRNA-seq'}</td><td>${fmt(r.cells)}</td><td>${escape(r.id)}</td></tr>${expandedStudies.has(r.id)?`<tr class="study-detail"><td colspan="8"><h3>${escape(humanText(r.title))}</h3><p>${escape(r.id)} · ${fmt(r.cells)} cells · ${fmt(r.genes)} genes · ${escape(r.species||'')}</p><p>${escape(r.message||'')}${r.id==='GSE175499'?' SFTS immune-cell reference; not a retinal or diabetic cohort.':''}${r.id==='GSE209872'?' Partial import: one corrupt deposited control matrix was excluded.':''}</p><p>${r.discoveryOrigin==='live GEO search'?'Discovered from current GEO records.':'Accession cited in the motivating review.'} Tissue categories are inferred from repository titles; consult source metadata.</p><a target="_blank" rel="noopener" href="${escape(r.source)}">View original repository record</a> · <button data-study="${escape(r.id)}">Open Dashboard</button></td></tr>`:''}`).join('')||'<tr><td colspan="8">No matching ready studies.</td></tr>';$('studyRange').textContent=rows.length?`${from+1}–${Math.min(from+size,rows.length)} of ${rows.length} rows`:'0 rows';$('pageNumber').textContent=`${studyPage+1} of ${Math.max(1,Math.ceil(rows.length/size))}`;$('previousPage').disabled=studyPage===0;$('nextPage').disabled=from+size>=rows.length;$('loadedStudies').querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{expandedStudies.has(b.dataset.expand)?expandedStudies.delete(b.dataset.expand):expandedStudies.add(b.dataset.expand);renderStudyTable()});$('loadedStudies').querySelectorAll('input[name=studyRow]').forEach(b=>b.onchange=()=>void loadStudy(b.value));$('loadedStudies').querySelectorAll('[data-study]').forEach(b=>b.onclick=async()=>{await loadStudy(b.dataset.study);setView('explore');window.scrollTo({top:0})})}

// Initialization follows all control bindings below.
function coord(i,axis){const ts=$('projection').value==='tsne';if(reclusterState){const j=reclusterState.lookup.get(i);if(j===undefined)return 0;return reclusterState[ts?(axis?'ty':'tx'):(axis?'y':'x')][j]}return cells[ts?(axis?'ty':'tx'):(axis?'y':'x')][i]}
$('projection').onchange=()=>{document.querySelector('.xaxis').textContent=$('projection').selectedOptions[0].text+' 1';document.querySelector('.yaxis').textContent=$('projection').selectedOptions[0].text+' 2';pan={x:0,y:0,z:1};draw();updateURL()};
function inPolygon(x,y,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [xi,yi]=poly[i],[xj,yj]=poly[j];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)inside=!inside}return inside}
function updateSelection(){$('selectionStatus').textContent=`Group 1: ${selectedA.size} cells · Group 2: ${selectedB.size} cells. ${[...selectedA].some(i=>selectedB.has(i))?'Selections overlap; redraw before testing.':''}`}
$('clearLasso').onclick=()=>{selectedA.clear();selectedB.clear();updateSelection();draw()};
$('originalMap').onclick=()=>{reclusterState=null;reclusterJob=null;$('originalMap').hidden=true;pan={x:0,y:0,z:1};filter()};
function ownerKey(){let k=sessionStorage.getItem('retinalens-owner-key');if(!k){k=prompt('Enter your Retina Spectacle owner access key to run this job. It is stored only for this browser session.');if(k)sessionStorage.setItem('retinalens-owner-key',k)}return k}
async function post(path,payload={}){const key=ownerKey();if(!key)throw Error('Owner access key is required to start this job.');const r=await fetch(API+path,{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Key':key},body:JSON.stringify(path.startsWith('/analysis/')?{...payload,revision:meta.revision}:payload)});const result=await r.json();if(!r.ok){if(r.status===401)sessionStorage.removeItem('retinalens-owner-key');throw Error(result.detail||'Request failed')}return result}
$('importReview').onclick=async()=>{try{await post('/import-review');status('Review discovery started. Existing successful imports will be reused.');await refreshStudies()}catch(e){status(e.message,true)}};
function populateSelectors(){if(!meta)return;const mode=$('selectionMode').value;const opts=mode==='sample'?meta.samples.map((s,i)=>({id:i,name:s})):reclusterState?[...new Set(reclusterState.cluster)].map(k=>({id:+k,name:'Subset C'+k})):meta.groups;for(const target of ['populationA','populationB'])$(target).innerHTML=opts.map(o=>`<option value="${o.id}">${escape(o.name)}</option>`).join('');$('populationA').disabled=$('populationB').disabled=mode==='lasso';if(mode!=='lasso'){$('populationA').options[0].selected=true;if($('populationB').options[1])$('populationB').options[1].selected=true}populationCounts()}
function populations(){if(!meta)return[[],[]];const mode=$('selectionMode').value,scope=new Set(visible);if(mode==='lasso')return[[...selectedA],[...selectedB]];return['populationA','populationB'].map(id=>{const groups=new Set([...$(id).selectedOptions].map(o=>+o.value));return(mode==='sample'?cells.sample:reclusterState?cells.cluster.map((c,i)=>reclusterState.lookup.has(i)?Number(reclusterState.cluster[reclusterState.lookup.get(i)]):-1):cells.cluster).map((c,i)=>groups.has(c)?i:-1).filter(i=>i>=0&&(!reclusterState||reclusterState.lookup.has(i))&&(!$('restrictCells').checked||scope.has(i)))})}
function populationCounts(){const[a,b]=populations();$('populationCounts').textContent=`Group 1: ${fmt(a.length)} cells. Group 2: ${fmt(b.length)} cells. Hold Command/Ctrl to select multiple groups.`}
$('selectionMode').onchange=populateSelectors;$('populationA').onchange=populationCounts;$('populationB').onchange=populationCounts;$('restrictCells').onchange=populationCounts;
async function waitJob(id){for(let attempt=0;attempt<720;attempt++){const item=await get(API+'/jobs/'+id);$('analysisStatus').textContent=item.message||item.status;if(item.status==='ready')return item.result;if(item.status==='failed')throw Error(item.message);await new Promise(resolve=>setTimeout(resolve,4000))}throw Error('The job is still running. Its results remain on the service; retry this same selection to reconnect.')}
$('runDE').onclick=async()=>{if(!meta)return;const[a,b]=populations();if(Math.min(a.length,b.length)<3){status('Select at least three cells in each population.',true);return}const bSet=new Set(b);if(a.some(i=>bSet.has(i))){status('Populations overlap. Choose disjoint groups or redraw the lasso.',true);return}const button=$('runDE');button.disabled=true;const id=meta.id;try{$('analysisStatus').textContent='Submitting differential-expression job…';const job=await post(`/analysis/${id}/differential`,{a,b,minPct:Number($('minPct').value),logfc:Number($('logfc').value)});deJob=job.id;deResult=await waitJob(job.id);deResult.study=id;deResult.revision=job.revision||'legacy';$('deResults').hidden=false;$('deSummary').textContent=`${id}: ${fmt(deResult.nA)} vs ${fmt(deResult.nB)} cells · ${fmt(deResult.testedGenes)} genes tested`;$('deMethods').textContent=deResult.method+' '+deResult.warning;renderDE()}catch(e){$('analysisStatus').textContent=e.message;status(e.message,true)}finally{button.disabled=false}};
$('runRecluster').onclick=async()=>{if(!meta)return;const a=$('reclusterLasso').checked?[...selectedA]:cells.cluster.map((g,i)=>[...$('reclusterGroups').selectedOptions].some(o=>+o.value===g)?i:-1).filter(i=>i>=0);if(a.length<12||a.length>50000){status('Select between 12 and 50,000 cells to recluster.',true);return}const button=$('runRecluster');button.disabled=true;const id=meta.id,revision=meta.revision;try{const job=await post(`/analysis/${id}/recluster`,{cells:a});const result=await waitJob(job.id);if(meta.id!==id||meta.revision!==revision)await loadStudy(id,false,revision);reclusterJob=job.id;reclusterState={...result,lookup:new Map(result.indices.map((x,i)=>[x,i]))};$('cluster').value='all';$('sample').value='all';$('originalMap').hidden=false;pan={x:0,y:0,z:1};setView('explore');filter();status('Subset reclustered. Use Original map to return to the complete study.')}catch(e){status(e.message,true)}finally{button.disabled=false}};
function renderDE(){if(!deResult)return;const sort=$('deSort').value,q=$('deSearch').value.toUpperCase();const rows=deResult.rows.filter(r=>r.gene.toUpperCase().includes(q)).sort((a,b)=>sort==='qvalue'?a.qvalue-b.qvalue:Math.abs(b[sort])-Math.abs(a[sort]));$('deTable').innerHTML=rows.slice(0,100).map(r=>`<tr><td><button class="genelink" data-gene="${escape(r.gene)}">${escape(r.gene)}</button></td><td>${r.log2FC.toFixed(3)}</td><td>${r.deltaPct.toFixed(1)}</td><td>${r.pvalue.toExponential(2)}</td><td>${r.qvalue.toExponential(2)}</td></tr>`).join('')||'<tr><td colspan="5">No genes meet these thresholds.</td></tr>';$('deTable').querySelectorAll('button').forEach(b=>b.onclick=async()=>{if(meta.id!==deResult.study||meta.revision!==deResult.revision)await loadStudy(deResult.study,false,deResult.revision);setView('explore');await selectGene(b.dataset.gene)});const data=deResult.rows;const max=Math.max(1,...data.map(r=>Math.abs(r.log2FC)));let svg='<svg viewBox="0 0 1000 370" role="img" aria-label="Differential expression scatter plot"><path d="M70 20V315H950 M70 165H950 M510 20V315" stroke="#d8e4dc" fill="none"/>';for(const tick of [-1,-.5,0,.5,1])svg+=`<text x="60" y="${169-tick*135}" text-anchor="end" font-size="12">${(tick*max).toFixed(1)}</text>`;for(const r of data){const x=510+r.deltaPct*4.3,y=165-r.log2FC/max*135;svg+=`<circle cx="${x}" cy="${y}" r="3" fill="${r.log2FC>=0?'#da7359':'#507fac'}" opacity=".7"><title>${escape(r.gene)}: log₂FC ${r.log2FC.toFixed(3)}, Δ detection ${r.deltaPct.toFixed(1)}%, q=${r.qvalue.toExponential(2)}</title></circle>`}svg+='<text x="375" y="357" font-size="16">Detection difference A − B (percentage points)</text><text x="10" y="18" font-size="14">log₂FC</text><text x="65" y="337" font-size="13">−100</text><text x="505" y="337" font-size="13">0</text><text x="925" y="337" font-size="13">100</text></svg>';$('deScatter').innerHTML=svg}
$('deSearch').oninput=renderDE;$('deSort').onchange=renderDE;$('deCsv').onclick=()=>{if(!deResult)return;const keys=['gene','log2FC','deltaPct','pctA','pctB','meanA','meanB','pvalue','qvalue'];download(`${deResult.study}-exploratory-DE.csv`,csv([keys,...deResult.rows.map(r=>keys.map(k=>r[k]))]))};$('deXlsx').onclick=async()=>{if(!deJob)return;const button=$('deXlsx');button.disabled=true;try{const r=await fetch(API+'/jobs/'+deJob+'/xlsx');if(!r.ok)throw Error('The Excel file could not be downloaded. Please retry.');download(`Retina-Spectacle-${deJob}.xlsx`,await r.blob(),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}catch(e){status(e.message,true)}finally{button.disabled=false}};
async function selectViolin(query){if(!meta||!genes)return;const index=genes.findIndex(g=>g.toUpperCase()===query.trim().toUpperCase());if(index<0){status('This violin gene is not retained in the selected study.',true);return}const version=++violinVersion,studyVersion=loadVersion;try{const v=await expression(index);if(version!==violinVersion||studyVersion!==loadVersion)return;$('violinGene').value=genes[index];$('selectedGene').textContent=genes[index];renderViolins([index],[v]);renderGene();status('');updateURL()}catch(e){status(e.message,true)}}
function renderViolins(ids,vs){violinIds=ids;violinValues=vs;const sample=document.querySelector('[name=violinIdentity]:checked').value==='sample';const groups=sample?meta.samples.map((name,id)=>({name,id})):meta.groups;const membership=sample?cells.sample:cells.cluster;let html='';ids.forEach((id,j)=>{const v=vs[j];let max=0;for(const x of v)max=Math.max(max,x);max=Math.max(max,.01);const width=Math.max(300,$('violins').clientWidth),height=650,L=58,R=width-16,T=62,B=530,step=(R-L)/groups.length;let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(genes[id])} violin distributions"><rect width="${width}" height="${height}" fill="white"/><text x="${width/2}" y="30" font-size="18" text-anchor="middle">${escape(genes[id])}</text><text x="${width/2}" y="50" font-size="12" text-anchor="middle">${escape(meta.id)} · ${sample?'samples':'cell groups'} · all retained cells</text>`;for(let k=0;k<=5;k++){const y=B-(B-T)*k/5;svg+=`<path d="M${L} ${y}H${R}" stroke="#e8e8e8"/><text x="${L-8}" y="${y+4}" text-anchor="end" font-size="12">${(max*k/5).toFixed(1)}</text>`}svg+=`<path d="M${L} ${T}V${B}H${R}" fill="none" stroke="#888"/><text x="17" y="390" font-size="15" text-anchor="middle" transform="rotate(-90 17 390)">Expression level · ln(1 + CP10K)</text>`;groups.forEach((g,k)=>{const arr=[];for(let i=0;i<v.length;i++)if(membership[i]===g.id)arr.push(v[i]);const mean=arr.reduce((a,b)=>a+b,0)/Math.max(arr.length,1);const sd=Math.sqrt(arr.reduce((a,b)=>a+(b-mean)**2,0)/Math.max(arr.length,1));const bw=Math.max(.08,1.06*sd*Math.pow(Math.max(arr.length,1),-.2));const grid=Array.from({length:45},(_,i)=>max*i/44),dens=grid.map(y=>arr.reduce((sum,x)=>sum+Math.exp(-.5*((y-x)/bw)**2),0)/Math.max(arr.length,1));const peak=Math.max(...dens,.001),cx=L+step*(k+.5),half=Math.min(25,step*.43);const left=grid.map((y,i)=>[cx-dens[i]/peak*half,B-y/max*(B-T)]),right=grid.map((y,i)=>[cx+dens[i]/peak*half,B-y/max*(B-T)]).reverse();svg+=`<polygon points="${[...left,...right].map(p=>p.join(',')).join(' ')}" fill="${palette[k%palette.length]}" fill-opacity=".8" stroke="#333" stroke-width=".6"><title>${escape(g.name)}, n=${arr.length}, mean=${mean.toFixed(3)}</title></polygon><text x="${cx}" y="${B+14}" font-size="11" text-anchor="end" transform="rotate(-65 ${cx} ${B+14})">${escape(sample?g.name:'C'+g.id)}</text>`});svg+=`<text x="${width/2}" y="630" text-anchor="middle" font-size="11">Distributions include zero-expression cells</text></svg>`;html+=svg});$('violins').innerHTML=html}


async function restoreJob(id){try{const item=await get(API+"/jobs/"+id);if(item.kind==='recluster'){const result=item.status==='ready'?item.result:await waitJob(id);if(!meta||meta.id!==item.study||meta.revision!==item.revision)await loadStudy(item.study,false,item.revision);reclusterJob=id;reclusterState={...result,lookup:new Map(result.indices.map((x,i)=>[x,i]))};$('cluster').value='all';$('sample').value='all';$('originalMap').hidden=false;pan={x:0,y:0,z:1};setView('explore');filter();return}if(item.kind!=="differential")throw Error("This link is not a supported analysis result.");deJob=id;deResult=item.status==="ready"?item.result:await waitJob(id);deResult.study=item.study;deResult.revision=item.revision||'legacy';$("deResults").hidden=false;$("deSummary").textContent=`${item.study}: ${fmt(deResult.nA)} vs ${fmt(deResult.nB)} cells · ${fmt(deResult.testedGenes)} genes tested`;$("deMethods").textContent=deResult.method+" "+deResult.warning;renderDE();updateURL()}catch(e){status(e.message,true)}}

function renderFreshness(f){const when=f.lastCheckedAt?new Date(f.lastCheckedAt*1000).toLocaleString():'First check in progress';$('freshnessText').textContent=(f.status==='checking'?'Checking public repositories…':f.status==='failed'?'Source check failed; completed data remain available. Last successful check: '+when:'Last source check: '+when)+(f.errors?.length?' · '+f.errors.length+' sources need another check':'')+(f.mode==='scheduled'?' · Automatic checks run on a 30-minute schedule.':' · Visits share a check every 30 minutes.');const row=meta&&studyRows.find(r=>r.id===meta.id);$('newVersion').hidden=!(row&&(row.activeVersion||'legacy')!==(meta.revision||'legacy'));}
async function checkFreshness(){if(sessionPaused)return;try{const r=await fetch(API+'/refresh',{method:'POST'});if(!r.ok)throw Error('Source check unavailable');renderFreshness(await r.json());}catch(e){$('freshnessText').textContent='Could not check sources right now. Completed datasets remain available.';}}
$('newVersion').onclick=()=>loadStudy(meta.id);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void checkFreshness()});
setInterval(()=>{if(document.visibilityState==='visible')void checkFreshness()},1800000);

function renderHeatmap(ids,vs){const rows=meta.groups,width=Math.max(430,$('heatmap').clientWidth||480),left=153,step=(width-left-12)/ids.length,rowHeight=26,height=135+rows.length*rowHeight;let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Gene expression heatmap">`;const matrix=rows.map(g=>vs.map(v=>stats(cells.cluster.map((c,i)=>c===g.id?i:-1).filter(i=>i>=0),v).mean));const max=Math.max(.01,...matrix.flat());ids.forEach((id,j)=>svg+=`<text x="${left+step*(j+.5)}" y="30" text-anchor="middle" font-size="11">${escape(genes[id])}</text>`);rows.forEach((g,i)=>{svg+=`<text x="8" y="${60+i*rowHeight}" font-size="11"><title>${escape(g.name)}</title>${escape(g.name.length>23?g.name.slice(0,22)+'…':g.name)}</text>`;matrix[i].forEach((v,j)=>svg+=`<rect x="${left+j*step}" y="${43+i*rowHeight}" width="${step-3}" height="23" fill="${geneColor(v,max)}"><title>${escape(g.name)} · ${escape(genes[ids[j]])}: ${v.toFixed(4)}</title></rect>`)});svg+=`<text x="8" y="${83+rows.length*rowHeight}" font-size="11">Group means include zero-expression cells</text><text x="8" y="${103+rows.length*rowHeight}" font-size="11">Shared color scale: 0–${max.toFixed(2)} ln(1 + CP10K)</text></svg>`;$('heatmap').innerHTML=svg;}

function configureMetadata(){metadataColors={};$('color').querySelectorAll('[data-metadata]').forEach(o=>o.remove());const samples=meta.samples.map(name=>{const m=meta.sampleMetadata?.[name]||{};const pairs={};for(const line of m.characteristics_ch1||[]){const pos=line.indexOf(':');if(pos>0)pairs[line.slice(0,pos).trim()]=line.slice(pos+1).trim()}return pairs});const keys=[...new Set(samples.flatMap(x=>Object.keys(x)))];for(const field of keys){const labels=[...new Set(samples.map(x=>x[field]||'Not deposited'))];if(labels.length<2)continue;const key='metadata:'+field;metadataColors[key]={labels,codes:samples.map(x=>labels.indexOf(x[field]||'Not deposited'))};const option=document.createElement('option');option.value=key;option.dataset.metadata='true';option.textContent='Metadata: '+field;$('color').append(option)}}
$('studySearch').oninput=()=>{studyPage=0;renderStudyTable()};$('studySort').onchange=()=>{studyPage=0;renderStudyTable()};
$('rowsPerPage').onchange=()=>{studyPage=0;renderStudyTable()};$('previousPage').onclick=()=>{studyPage--;renderStudyTable()};$('nextPage').onclick=()=>{studyPage++;renderStudyTable()};
document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{$('studySort').value=b.dataset.sort;renderStudyTable()});
document.querySelectorAll('[data-tissue]').forEach(b=>b.onclick=()=>{activeTissue=b.dataset.tissue;studyPage=0;document.querySelectorAll('[data-tissue]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});renderStudyTable()});
document.querySelectorAll('[data-left]').forEach(b=>b.onclick=()=>setView(b.dataset.left));document.querySelectorAll('[data-right]').forEach(b=>b.onclick=()=>{if(b.dataset.right==='group2'&&currentView!=='analysis')setView('analysis');setRightPane(b.dataset.right)});
document.querySelectorAll('[data-open-dashboard]').forEach(b=>b.onclick=()=>setView('explore'));document.querySelectorAll('[data-open-studies]').forEach(b=>b.onclick=()=>setView('studies'));
$('toggleNav').onclick=()=>{document.body.classList.toggle(innerWidth<=600?'nav-open':'nav-collapsed');requestAnimationFrame(draw)};
$('restartApp').onclick=$('resumeApp').onclick=()=>location.reload();$('stopApp').onclick=()=>{sessionPaused=true;$('pausedSession').hidden=false};
$('interactiveToggle').onclick=()=>{interactive=!interactive;$('interactiveToggle').setAttribute('aria-checked',String(interactive));document.body.classList.toggle('static-plots',!interactive);$('tooltip').hidden=true};
$('showLabels').onchange=draw;
$('violinForm').onsubmit=e=>{e.preventDefault();void selectViolin($('violinGene').value)};$('violinGene').oninput=()=>{if(!genes)return;const q=$('violinGene').value.toUpperCase();$('geneOptions').innerHTML=genes.filter(g=>g.toUpperCase().startsWith(q)).slice(0,30).map(g=>`<option value="${escape(g)}">`).join('')};
document.querySelectorAll('[name=violinIdentity]').forEach(r=>r.onchange=()=>{if(violinIds.length)renderViolins(violinIds,violinValues)});
$('saveViolin').onclick=()=>{if(meta&&$('violins').firstElementChild)download(`${meta.id}-${genes[violinIds[0]]}-violin.svg`,$('violins').firstElementChild.outerHTML,'image/svg+xml')};
$('ownerKey').value=sessionStorage.getItem('retinalens-owner-key')||'';$('ownerKey').onchange=()=>{const key=$('ownerKey').value.trim();if(key)sessionStorage.setItem('retinalens-owner-key',key);else sessionStorage.removeItem('retinalens-owner-key')};
void get(API+'/health').then(h=>{analysesEnabled=h.analysesEnabled===true;document.body.classList.toggle('public-only',!analysesEnabled);$('runDE').disabled=$('runRecluster').disabled=!analysesEnabled}).catch(()=>{});setView(initial.get('view')==='analysis'&&!initial.get('job')?'saved':initial.get('view')||'studies');void checkFreshness();await refreshStudies();if(initial.get('job'))void restoreJob(initial.get('job'));setInterval(()=>{if(!sessionPaused)void refreshStudies()},15000);

